import axios from 'axios';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:5000/api',
  timeout: 30000,
});

// Attach token to every request
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('smm_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Auto-logout on 401
api.interceptors.response.use(
  (res) => res,
  (err) => {
    if (err.response?.status === 401) {
      localStorage.removeItem('smm_token');
      window.location.href = '/login';
    }
    return Promise.reject(err);
  }
);

// ─── Auth ────────────────────────────────────────────────────────────────────
export const authAPI = {
  login: (data) => api.post('/auth/login', data),
  register: (data) => api.post('/auth/register', data),
  me: () => api.get('/auth/me'),
  instagramOAuth: () => api.get('/auth/instagram'),
};

// ─── Accounts ────────────────────────────────────────────────────────────────
export const accountsAPI = {
  getAll: () => api.get('/accounts'),
  getByUser: (userId) => api.get(`/accounts/user/${userId}`),
  create: (data) => api.post('/accounts', data),
  createAutomation: (data) => api.post('/accounts/automation', data),
  updateWarmup: (id, data) => api.patch(`/accounts/${id}/warmup`, data),
  disconnect: (id) => api.delete(`/accounts/${id}`),
  verify: (id) => api.post(`/accounts/${id}/verify`),
  verifyAll: () => api.post('/accounts/verify-all'),
};

// ─── Posts ───────────────────────────────────────────────────────────────────
export const postsAPI = {
  getAll: (params) => api.get('/posts', { params }),
  getOne: (id) => api.get(`/posts/${id}`),
  create: (formData) => api.post('/posts', formData, {
    headers: { 'Content-Type': 'multipart/form-data' }
  }),
  delete: (id) => api.delete(`/posts/${id}`),
  retry: (id) => api.post(`/posts/${id}/retry`),
  stop: (id) => api.post(`/posts/${id}/stop`),
};

// ─── Schedule ────────────────────────────────────────────────────────────────
export const scheduleAPI = {
  getUpcoming: (params) => api.get('/schedule', { params }),
  reschedule: (id, scheduledAt) => api.patch(`/schedule/${id}`, { scheduledAt }),
};

// ─── Notifications ───────────────────────────────────────────────────────────
export const notifAPI = {
  getAll: (params) => api.get('/notifications', { params }),
  markRead: (id) => api.patch(`/notifications/${id}/read`),
  markAllRead: () => api.patch('/notifications/mark-all-read'),
};

// ─── Analytics ───────────────────────────────────────────────────────────────
export const analyticsAPI = {
  getSummary: () => api.get('/analytics/summary'),
  getAccount: (id, days) => api.get(`/analytics/account/${id}`, { params: { days } }),
};

// ─── Post Browser ────────────────────────────────────────────────────────────
export const postBrowserAPI = {
  getPosts: (accountId, limit = 20) => api.get(`/accounts/${accountId}/posts`, { params: { limit } }),
};

// ─── Post Link Scraper (Instagram & Threads) ───────────────────────────────────
export const scraperAPI = {
  runInstagram: (data) =>
    api.post('/scraper/instagram', data, { timeout: 300000 }),
  runThreads: (data) =>
    api.post('/scraper/threads', data, { timeout: 300000 }),
  exportInstagram: (results) =>
    api.post('/scraper/instagram/export', { results }, { responseType: 'blob' }),
  exportThreads: (results) =>
    api.post('/scraper/threads/export', { results }, { responseType: 'blob' }),
};

// ─── Amplify ─────────────────────────────────────────────────────────────────
export const amplifyAPI = {
  getAll: () => api.get('/amplify'),
  create: (data) => api.post('/amplify', data),
  stop: (id) => api.patch(`/amplify/${id}/stop`),
};

// ─── Warmup ──────────────────────────────────────────────────────────────────
export const warmupAPI = {
  getStats: () => api.get('/warmup/stats'),
  getLogs: () => api.get('/warmup/logs'),
};

export const aiAPI = {
  generateCaption:    (data)   => api.post('/ai/caption', data),
  generateVariations: (data)   => api.post('/ai/caption/variations', data),
  generateComments:   (data)   => api.post('/ai/comments', data),
  generateHashtags:   (data)   => api.post('/ai/hashtags', data),
  generateReply:      (data)   => api.post('/ai/reply', data),
  generateContent:    (data)   => api.post('/ai/content/generate', data, { timeout: 60000 }),
  scrapeNews:         (params) => api.get('/ai/scrape/news', { params }),
  scrapeTrends:       ()       => api.get('/ai/scrape/trends'),
  generateImagen:     (data)   => api.post('/ai/imagen/generate', data, { timeout: 90000 }),
  analyzeSentiment:   (data)   => api.post('/ai/sentiment/analyze', data),
  getYoutubeTrends:   (params) => api.get('/ai/youtube/trends', { params }),
  getScheduleStrategy: (params) => api.get('/ai/schedule/strategy', { params }),
  getWeeklySchedule:   (params) => api.get('/ai/schedule/weekly', { params }),
  getBatchSchedule:    (params) => api.get('/ai/schedule/batch', { params }),
  generateShortsIdea:  (data)   => api.post('/ai/youtube/shorts-idea', data),
};

export default api;
